@startuml

class User {
  + username : string
  + password : string
}

class Player extends User {
  + lives : int
  + score : int
}

class Admin extends User {
}

class Game {
  + name : string
  + minSpeed : float
  + speedIncreaseFactor : float
  + maxLength : float
  + minLength : float
  + isPublished : boolean
}

class HallOfFame {
  + highScores : List<int>
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
  + startingArrangement : List<CellPosition>
  + blocksAtStartCount : int
}

class CellPosition {
  + x : int
  + y : int
}

class GameSession {
  + currentScore : int
  + currentLives : int
  + currentLevelIndex : int
  + isPaused : boolean
}

Admin "1" -- "0..*" Game : manages
Game "1" -- "1" HallOfFame : has
Game "1" *-- "1..*" Level : contains
Game "1" *-- "1..*" Block : contains
Level "1" -- "1..*" CellPosition : uses
Level "1" -- "0..*" Block : contains

Player "0..*" -- "0..*" Game : plays
Player "1" -- "0..*" GameSession : participates in
GameSession "1" -- "1" Game : belongs to

@enduml

